// ---8<--- SHARED START ---8<---
// Copied verbatim into the "Validate Upload" Code node in
// workflows/demo-upload.json.
// tests/demo-workflow.test.js fails if they drift apart.
//
// The declared Content-Type is attacker-controlled, so the allowlist is
// enforced against the bytes. DOCX shares the ZIP signature with every
// other Office format; the check confirms the container, and extraction
// fails cleanly on a ZIP that is not a document.

function detectFileType(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length === 0) return null;

  // %PDF- at offset 0.
  if (buffer.length >= 5 && buffer.slice(0, 5).toString('latin1') === '%PDF-') return 'pdf';

  // ZIP local file header (PK\x03\x04) or empty-archive marker (PK\x05\x06).
  if (
    buffer.length >= 4 &&
    buffer[0] === 0x50 && buffer[1] === 0x4b &&
    ((buffer[2] === 0x03 && buffer[3] === 0x04) || (buffer[2] === 0x05 && buffer[3] === 0x06))
  ) {
    return 'docx';
  }

  // Plain text: valid UTF-8, no NUL bytes, and no C0 control characters
  // other than tab, newline and carriage return.
  //
  // A NUL anywhere disqualifies the file as text. This scan covers the whole
  // buffer, not a sample: a file that is clean ASCII for its first 8 KB and
  // binary afterward would otherwise pass, and the whole buffer is what gets
  // forwarded for extraction. At the 10 MB upload ceiling this is a memchr.
  if (buffer.includes(0x00)) return null;

  // Decode and control-character checks stay on a sample — they are per
  // character, and a document's encoding does not change halfway through.
  const sample = buffer.slice(0, 8192);

  const decoded = new TextDecoder('utf-8', { fatal: false }).decode(sample);
  if (decoded.includes('�')) return null;

  for (let i = 0; i < decoded.length; i++) {
    const code = decoded.charCodeAt(i);
    if (code < 0x20 && code !== 0x09 && code !== 0x0a && code !== 0x0d) return null;
  }

  return 'txt';
}

// --- node glue below the shared block -------------------------------------
// This node sits FIRST, ahead of the session check, for one mechanical
// reason: this.helpers.getBinaryDataBuffer reads the binary attached to the
// CURRENT input item, and the only item carrying the file is the webhook's.
// Verify Session is a sub-workflow whose output is plain JSON, so the file
// would already be gone by the time this ran downstream of it.
//
// The cost is that an unauthenticated caller can make us hash a buffer we
// have already received in full. That is CPU on bytes already paid for, it
// touches no database and no provider, and it fails closed.

const MAX_BYTES = 10485760;

const req = $('Webhook').first().json;
const cookieHeader = (req.headers && req.headers.cookie) || '';

// Rejections are returned, not thrown. A returned item routes through a
// plain If, where a thrown one would depend on the exact shape of n8n's
// error item -- which differs between node types and is not worth guessing.
function reject(code) {
  return [{ json: { ok: false, code: code, cookie_header: cookieHeader } }];
}

const item = $input.first();
const binary = item.binary || {};
const keys = Object.keys(binary);
// Whatever the multipart field is called. The frontend sends "file", but the
// property name is n8n's to choose and is not worth coupling to.
if (!keys.length) return reject('UNSUPPORTED_TYPE');

const key = keys[0];
const meta = binary[key] || {};

// N8N_DEFAULT_BINARY_DATA_MODE is filesystem, so the bytes are NOT inline on
// the item -- meta.data is empty and this helper is the only way to them.
const buffer = await this.helpers.getBinaryDataBuffer(0, key);

if (!buffer || !buffer.length) return reject('UNSUPPORTED_TYPE');
if (buffer.length > MAX_BYTES) return reject('FILE_TOO_LARGE');

// Against the bytes, never the declared Content-Type, which the caller owns.
const fileType = detectFileType(buffer);
if (!fileType) return reject('UNSUPPORTED_TYPE');

const filename = String(meta.fileName || 'document');

// Materialised here so part 2 is a pure addition: after Verify Session the
// binary is gone (a sub-workflow returns JSON), so the content has to cross
// that boundary as JSON or not at all. Text decodes now; PDF and DOCX go to
// Gemini as base64 anyway, which is the same encoding.
const isText = fileType === 'txt';

return [{
  json: {
    ok: true,
    cookie_header: cookieHeader,
    filename: filename,
    size: buffer.length,
    file_type: fileType,
    text: isText ? buffer.toString('utf8') : '',
    content_b64: isText ? '' : buffer.toString('base64'),
  },
}];

// Already decoded in Validate Upload. No model call for a .txt file:
// it costs tokens and can only lose fidelity against bytes we can read.
return [{ json: { text: $('Validate Upload').first().json.text || '' } }];

// ---8<--- SHARED START ---8<---
// Copied verbatim into the "Prepare Gemini Request" Code node in
// workflows/demo-upload.json.
// tests/demo-workflow.test.js fails if they drift apart.

const EXTRACTION_PROMPT = [
  'You are a content extractor. The text you produce will be indexed for a',
  'retrieval system that answers questions about this document, so it must be',
  'complete and faithful rather than readable prose.',
  '',
  'EXTRACTION RULES:',
  '',
  '1. Process every page from the first to the last, including front matter.',
  '   Specifications, safety notices, requirements, operating modes and',
  '   manufacturer details are frequently what people ask about. Do not skip them.',
  '',
  '2. SECTIONS: before each section or chapter, write its title on its own line',
  '   prefixed with "## " (for example: "## 5. Reset procedure"). Detect titles',
  '   from the layout -- numbered, bold, or set in a larger face -- and mark them',
  '   this way. This is the most important rule: the indexer splits the document',
  '   on these headings, and text with no headings is indexed as one block.',
  '',
  '3. TABLES: rewrite every table row as a standalone sentence. Instead of a',
  '   table with "code | description" columns, write each row as',
  '   "Code [code]: [description]". Each row must be intelligible on its own,',
  '   because rows are retrieved individually and without their header.',
  '',
  '4. IMAGES: describe only images carrying information not present in the text',
  '   (diagrams, component locations, wiring). Two sentences at most. Ignore',
  '   logos, watermarks and decorative images.',
  '',
  '5. FIDELITY: reproduce exactly all codes, passwords, key sequences, serial',
  '   numbers, menu names, and specifications (dimensions, voltages, speeds,',
  '   capacities). These are the details people ask about, and an approximation',
  '   is worse than an omission.',
  '',
  "6. Use the document's original language. Do not translate, do not summarise,",
  '   and do not add commentary of your own.',
  '',
  '7. TABLE OF CONTENTS: skip only pages that are a table of contents -- lists of',
  '   titles followed by page numbers and dot leaders. Do not reproduce them. The',
  '   pages around a table of contents are ordinary content and must be extracted.',
  '',
  '8. Omit page numbers, repeated headers and footers, and watermarks.',
  '',
  'COMPLETION RULES:',
  '- This is a single request. There is no follow-up message and no continuation.',
  '- Do not write phrases such as "continued below" or "the rest of the document".',
  '- Produce the extraction and nothing else: no preamble, no closing remark.',
].join('\n');

// --- node glue below the shared block -------------------------------------
const file = $('Validate Upload').first().json;

// Gemini's inline_data takes the base64 Validate Upload already produced.
// DOCX is sent with its real Office mime type; if the model rejects it the
// error output marks the upload failed rather than half-succeeding.
const MIME = {
  pdf: 'application/pdf',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
};

return [{
  json: {
    requestBody: {
      contents: [{
        parts: [
          { inline_data: { mime_type: MIME[file.file_type] || 'application/pdf',
                           data: file.content_b64 } },
          { text: 'Extract the contents of this document following the system instructions.' },
        ],
      }],
      systemInstruction: { parts: [{ text: EXTRACTION_PROMPT }] },
      generationConfig: {
        maxOutputTokens: 65536,
        // Extraction, not authorship. Anything higher invents structure.
        temperature: 0.1,
        thinkingConfig: { thinkingLevel: 'minimal' },
      },
    },
  },
}];

// Gemini returns the text split across parts. Joining every part matters:
// taking parts[0] alone silently truncates a long document to its first
// fragment, and the loss looks exactly like a short source file.
const res = $input.first().json || {};

const candidate = (res.candidates || [])[0];
if (!candidate) {
  // A safety block or a quota refusal lands here with no candidate at all.
  throw new Error('Gemini returned no candidate: ' + JSON.stringify(res).slice(0, 400));
}

const parts = (candidate.content && candidate.content.parts) || [];
const text = parts.map(function (p) { return p.text || ''; }).join('');

return [{ json: { text: text } }];

// ---8<--- SHARED START ---8<---
// Copied verbatim into the "Prepare Chunks" Code node in
// workflows/demo-upload.json.
// tests/demo-workflow.test.js fails if they drift apart.
//
// Generalised from the ingestion workflow's chunker: no Drive file_id,
// no last_modified, plus a hard ceiling so one dense document cannot
// exhaust the embedding budget.

const TOKEN_LIMIT = 350;
const OVERLAP_TOKENS = 75;
const MAX_CHUNKS = 600;

function toTokens(text) {
  return text.split(/\s+/).filter(Boolean);
}

function chunkDocument(fileName, text, options) {
  const opts = options || {};
  const tokenLimit = opts.tokenLimit || TOKEN_LIMIT;
  const overlap = opts.overlap === undefined ? OVERLAP_TOKENS : opts.overlap;
  const maxChunks = opts.maxChunks || MAX_CHUNKS;

  const name = String(fileName || 'document');
  const title = name.replace(/\.[^.]+$/, '');
  const body = typeof text === 'string' ? text : '';
  if (!body.trim()) return [];

  // Split on "## " headings emitted by the extraction prompt. Content
  // before the first heading belongs to the document itself.
  const sections = [];
  let heading = title;
  let buffer = [];
  for (const line of body.split('\n')) {
    const match = line.match(/^##\s+(.+)$/);
    if (match) {
      if (buffer.length) {
        sections.push({ heading: heading, content: buffer.join('\n') });
        buffer = [];
      }
      heading = match[1].trim();
    } else {
      buffer.push(line);
    }
  }
  if (buffer.length) sections.push({ heading: heading, content: buffer.join('\n') });

  const chunks = [];
  const seen = new Set();
  let chunkIndex = 0;

  for (const section of sections) {
    const sectionText = section.content.trim();
    if (!sectionText) continue;

    const tokens = toTokens(sectionText);
    if (!tokens.length) continue;

    let idx = 0;
    while (idx < tokens.length) {
      const window = tokens.slice(idx, idx + tokenLimit).join(' ');

      // Prefix with title and heading so a retrieved chunk carries its
      // own context -- the same trick the ingestion chunker uses.
      const embeddingText = title + ' — ' + section.heading + '\n\n' + window;

      // De-duplicate on content, not on the heading-prefixed text: the
      // same paragraph repeated under two different headings is still
      // the same fact, and indexing it twice wastes embedding budget.
      if (!seen.has(window)) {
        seen.add(window);
        chunks.push({
          text: embeddingText,
          section_heading: section.heading,
          chunk_index: chunkIndex,
          original_file_name: name,
        });
        chunkIndex++;

        if (chunks.length > maxChunks) {
          throw new Error(
            'Document is too large for the demo: over ' + maxChunks +
            ' chunks. Try a shorter document.'
          );
        }
      }

      // Last window: stop. Otherwise advance by the non-overlapping span.
      idx += (tokens.length - idx <= tokenLimit) ? tokens.length : (tokenLimit - overlap);
    }
  }

  return chunks;
}

// --- node glue below the shared block -------------------------------------
// Reached from either extraction branch, which both hand over { text }.
const text = ($input.first().json || {}).text || '';
const file = $('Validate Upload').first().json;
const sessionId = $('Verify Session').first().json.session_id;

// Returned, not thrown, so the caller routes through an If rather than
// depending on the shape of an n8n error item.
function fail(code) {
  return [{ json: { ok: false, code: code, total_chunks: 0 } }];
}

if (!text.trim()) return fail('NO_TEXT_LAYER');

let chunks;
try {
  chunks = chunkDocument(file.filename, text);
} catch (e) {
  // chunkDocument throws past MAX_CHUNKS. A scanned PDF is the common case
  // for empty output; an oversized one is the common case for this.
  return fail('NO_TEXT_LAYER');
}

// A document that produced text but no chunks is text-free in every way
// that matters here -- whitespace, or headings with nothing under them.
if (!chunks.length) return fail('NO_TEXT_LAYER');

// One item per batch: each becomes one embed call and one INSERT.
const out = [];
for (let i = 0; i < chunks.length; i += 100) {
  const batch = chunks.slice(i, i + 100);
  out.push({
    json: {
      ok: true,
      session_id: sessionId,
      total_chunks: chunks.length,
      chunks: batch,
      requestBody: {
        requests: batch.map(function (c) {
          return {
            model: 'models/gemini-embedding-001',
            content: { parts: [{ text: c.text }] },
            // RETRIEVAL_DOCUMENT, paired with RETRIEVAL_QUERY at search
            // time. Mismatching the two costs real retrieval quality.
            taskType: 'RETRIEVAL_DOCUMENT',
            title: c.original_file_name.replace(/\.[^.]+$/, '') + ' \u2014 ' + c.section_heading,
            outputDimensionality: 1536,
          };
        }),
      },
    },
  });
}

return out;

// Pairs each embedding back with its chunk and hands the batch over as a
// single JSON parameter.
//
// L2 normalisation is NOT optional: gemini-embedding-001 returns
// pre-normalised vectors only at 3072 dimensions. At the 1536 used here the
// vectors come back unnormalised, and demo_hybrid_search assumes unit length
// -- skip this and cosine distance silently ranks by magnitude.
function l2normalize(v) {
  let norm = 0;
  for (const x of v) norm += x * x;
  norm = Math.sqrt(norm);
  return norm > 0 ? v.map(function (x) { return x / norm; }) : v;
}

// This node runs ONCE for all items, not once per item, so it must loop.
// Chunk Document emits one item per batch and Embed Chunks preserves that
// count, so the two lists line up index for index -- the same pairing
// ingestion.json's own Format for Insert does.
const items = $input.all();
const batches = $('Chunk Document').all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const res = items[i].json || {};
  const embeddings = res.embeddings;
  if (!Array.isArray(embeddings)) {
    throw new Error('Embedding response ' + i + ' had no embeddings array: ' +
      JSON.stringify(res).slice(0, 400));
  }

  const src = batches[i].json;
  const chunks = src.chunks;

  if (embeddings.length !== chunks.length) {
    // Silently zipping mismatched arrays would attach each chunk's text to
    // another chunk's vector -- retrieval would then return confidently
    // wrong passages with nothing in the data to show why.
    throw new Error('Batch ' + i + ': embedding count ' + embeddings.length +
      ' does not match chunk count ' + chunks.length);
  }

  const rows = chunks.map(function (c, j) {
    const vec = l2normalize(embeddings[j].values);
    return {
      content: c.text,
      metadata: {
        file_name: c.original_file_name,
        section_heading: c.section_heading,
        chunk_index: c.chunk_index,
      },
      // pgvector's text input format.
      embedding: '[' + vec.join(',') + ']',
    };
  });

  out.push({ json: { session_id: src.session_id, rows_json: JSON.stringify(rows) } });
}

return out;
